func simd_g_i8x16_popcnt(a V128) V128 {
	lut := archsimd.LoadUint64x2Array(&simdGPopcntLUT).ReshapeToUint8s().BitsToInt8()
	m := archsimd.LoadUint64x2Array(&simdGNibbleMask).ReshapeToUint8s().BitsToInt8()
	lo := a.ReshapeToUint8s().BitsToInt8().And(m)
	hi := a.ReshapeToUint16s().ShiftAllRight(4).ReshapeToUint64s().ReshapeToUint8s().BitsToInt8().And(m)
	return lut.PermuteOrZero(lo).Add(lut.PermuteOrZero(hi)).ToBits().ReshapeToUint64s()
}

