func simd_g_i64x2_mul(a V128, b V128) V128 {
	x, y := a.ReshapeToUint32s(), b.ReshapeToUint32s()
	lo := x.MulWidenEven(y)
	t1 := a.ShiftAllRight(32).ReshapeToUint32s().MulWidenEven(y)
	t2 := x.MulWidenEven(b.ShiftAllRight(32).ReshapeToUint32s())
	return lo.Add(t1.Add(t2).ShiftAllLeft(32))
}

