func simd_g_f32x4_min(a V128, b V128) V128 {
	x, y := a.ReshapeToUint32s().BitsToFloat32(), b.ReshapeToUint32s().BitsToFloat32()
	sel := x.Less(y).ToInt32x4().ToBits().ReshapeToUint64s()
	eq := x.Equal(y).ToInt32x4().ToBits().ReshapeToUint64s()
	nan := x.IsNaN().Or(y.IsNaN()).ToInt32x4().ToBits().ReshapeToUint64s()
	r := a.And(sel).Or(b.AndNot(sel))
	r = r.AndNot(eq).Or(a.Or(b).And(eq))
	return r.AndNot(nan).Or(archsimd.BroadcastUint32x4(0x7fc00000).ReshapeToUint64s().And(nan))
}

