	eq := x.Equal(y).ToInt32x4().ToBits().ReshapeToUint64s()
	nan := x.IsNaN().Or(y.IsNaN()).ToInt32x4().ToBits().ReshapeToUint64s()
	r := a.And(sel).Or(b.AndNot(sel))
	r = r.AndNot(eq).Or(a.And(b).And(eq))
